(function(){
  var leaves=[];
  var dust=[];
  var nLeaves=46;
  var nDust=70;
  function rand(a,b){return a+Math.random()*(b-a);}
  function mkLeaf(){
    var side = Math.random()<0.5?0:1;
    return {
      x: side===0? rand(0,W()*0.32) : rand(W()*0.68,W()),
      y: rand(-H()*0.3,H()*0.1),
      speedY: rand(6,14)/60,
      speedX: rand(-6,6)/60,
      size: rand(5,11),
      rot: rand(0,Math.PI*2),
      rotSpeed: rand(-0.6,0.6)/60,
      sway: rand(0.5,1.5),
      phase: rand(0,Math.PI*2),
      color: PALETTE[Math.floor(rand(0,3))],
      alpha: rand(0.45,0.85)
    };
  }
  function mkDust(){
    var side = Math.random()<0.5?0:1;
    return {
      x: side===0? rand(0,W()*0.28) : rand(W()*0.72,W()),
      y: rand(0,H()),
      r: rand(0.6,2.2),
      speed: rand(2,8)/60,
      drift: rand(-4,4)/60,
      alpha: rand(0.2,0.6),
      flickerPhase: rand(0,Math.PI*2),
      flickerSpeed: rand(0.01,0.03)
    };
  }
  for(var i=0;i<nLeaves;i++) leaves.push(mkLeaf());
  for(var j=0;j<nDust;j++) dust.push(mkDust());

  var t=0;
  function frame(){
    t+=1;
    var w=W(), h=H();
    ctx.clearRect(0,0,w,h);

    // soft warm rays from top corners
    ctx.save();
    ctx.globalCompositeOperation='lighter';
    var grad1=ctx.createRadialGradient(w*0.1,h*0.05,0,w*0.1,h*0.05,h*0.5);
    grad1.addColorStop(0, hexA(PALETTE[1],0.18));
    grad1.addColorStop(1, hexA(PALETTE[1],0));
    ctx.fillStyle=grad1;
    ctx.fillRect(0,0,w,h);

    var grad2=ctx.createRadialGradient(w*0.92,h*0.95,0,w*0.92,h*0.95,h*0.5);
    grad2.addColorStop(0, hexA(PALETTE[0],0.14));
    grad2.addColorStop(1, hexA(PALETTE[0],0));
    ctx.fillStyle=grad2;
    ctx.fillRect(0,0,w,h);
    ctx.restore();

    // dust / light specks
    for(var k=0;k<dust.length;k++){
      var d=dust[k];
      d.y -= d.speed;
      d.x += d.drift + Math.sin((t+d.flickerPhase)*0.02)*0.15;
      d.flickerPhase+=d.flickerSpeed;
      if(d.y< -10){ d.y=h+10; }
      if(d.x<0) d.x=0; if(d.x>w) d.x=w;
      var fl = 0.5+0.5*Math.sin(t*d.flickerSpeed+d.flickerPhase);
      ctx.beginPath();
      ctx.fillStyle = hexA(PALETTE[1], d.alpha*fl);
      ctx.arc(d.x,d.y,d.r,0,Math.PI*2);
      ctx.fill();
    }

    // falling leaves
    for(var m=0;m<leaves.length;m++){
      var lf=leaves[m];
      lf.y += lf.speedY*6;
      lf.x += lf.speedX*2 + Math.sin(t*0.01+lf.phase)*lf.sway*0.3;
      lf.rot += lf.rotSpeed;
      if(lf.y> h+20){
        var nl = mkLeaf();
        nl.y = -20;
        leaves[m]=nl;
        continue;
      }
      ctx.save();
      ctx.translate(lf.x,lf.y);
      ctx.rotate(lf.rot);
      ctx.globalAlpha=lf.alpha;
      ctx.fillStyle=lf.color;
      ctx.beginPath();
      ctx.ellipse(0,0,lf.size,lf.size*0.55,0,0,Math.PI*2);
      ctx.fill();
      ctx.restore();
    }

    requestAnimationFrame(frame);
  }

  function hexA(hex, a){
    var c = hex.replace('#','');
    var r=parseInt(c.substring(0,2),16);
    var g=parseInt(c.substring(2,4),16);
    var b=parseInt(c.substring(4,6),16);
    return 'rgba('+r+','+g+','+b+','+a+')';
  }

  requestAnimationFrame(frame);
})();
